// base32: 4,000,000 generated bytes encoded as Base32 (RFC 4648, groups of
// 5 bytes as 8 letters of A-Z2-7) and decoded again. Prints the length of
// the text, a position-weighted checksum, and 1 when decoding gives the
// bytes back.

const ABC: &[u8; 32] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

fn main() {
    let n = 4_000_000usize;
    let data: Vec<u8> = (0..n as i64).map(|i| ((i * 2654435761) >> 13 & 255) as u8).collect();
    let mut text = Vec::with_capacity(n / 5 * 8);
    for g in data.chunks(5) {
        let v = g.iter().fold(0u64, |v, &b| v << 8 | b as u64);
        for k in 0..8 {
            text.push(ABC[(v >> (35 - 5 * k) & 31) as usize]);
        }
    }
    let check: i64 = text.iter().enumerate().map(|(i, &c)| c as i64 * (i as i64 % 251 + 1)).sum();
    let mut back = Vec::with_capacity(n);
    for g in text.chunks(8) {
        let v = g.iter().fold(0u64, |v, &c| v << 5 | if c >= b'A' { (c - b'A') as u64 } else { (c - b'2' + 26) as u64 });
        for k in 0..5 {
            back.push((v >> (32 - 8 * k)) as u8);
        }
    }
    println!("{} {} {}", text.len(), check, (back == data) as i32);
}
